def solve():
    solutions = []
    # x = n+1, so x >= 1
    # x^2 + 1 = 2^c * 5^d where c in {0, 1}
    # n+2 = x+1 = 2^a * 5^b
    for d in range(100):
        # Case c=0: x^2 + 1 = 5^d
        val0 = 5**d
        x0 = int((val0 - 1)**0.5)
        if x0*x0 == val0 - 1:
            n = x0 - 1
            if n >= 0:
                # check n+2 = 2^a * 5^b
                m = n + 2
                is_valid = True
                temp_m = m
                a, b = 0, 0
                while temp_m > 0 and temp_m % 2 == 0:
                    a += 1
                    temp_m //= 2
                while temp_m > 0 and temp_m % 5 == 0:
                    b += 1
                    temp_m //= 5
                if temp_m == 1:
                    # Check divisibility
                    if (m * (x0*x0 + 1)) <= 20**(n+1) and (20**(n+1)) % (m * (x0*x0 + 1)) == 0:
                        solutions.append(n)

        # Case c=1: x^2 + 1 = 2 * 5^d
        val1 = 2 * 5**d
        x1 = int((val1 - 1)**0.5)
        if x1*x1 == val1 - 1:
            n = x1 - 1
            if n >= 0:
                m = n + 2
                is_valid = True
                temp_m = m
                a, b = 0, 0
                while temp_m > 0 and temp_m % 2 == 0:
                    a += 1
                    temp_m //= 2
                while temp_m > 0 and temp_m % 5 == 0:
                    b += 1
                    temp_m //= 5
                if temp_m == 1:
                    if (m * (x1*x1 + 1)) <= 20**(n+1) and (20**(n+1)) % (m * (x1*x1 + 1)) == 0:
                        solutions.append(n)
    return sorted(list(set(solutions)))

